arguments.command:
cd /tmp/sv-21ea6ff6e7b9456fb690b04ea9b5eb14 && \
# Extract addresses from the crash log for libmonosgen-2.0.so frames
ADDRS="0x222098 0x2241ac 0x1abc80 0x1abd14 0x16dfa4 0x16db6c 0x16de04" && \
# Use dynamic symbols to find nearest function for each address
for addr in $ADDRS; do
  # Find the nearest symbol below this address
  match=$(nm -D --defined-only libmonosgen-2.0.so.sym2 2>/dev/null | awk -v a="$addr" '
    BEGIN { gsub("0x","",a); best=""; bestaddr=0 }
    { 
      if (strtonum("0x"$1) <= strtonum("0x"a) && strtonum("0x"$1) > bestaddr) {
        bestaddr = strtonum("0x"$1);
        best = $3;
        bestoff = $1;
      }
    }
    END { if (best != "") printf "%s + 0x%x (%s)\n", best, strtonum("0x"a) - bestaddr, a; else print "???" }
  ')
  echo "  #$(printf '%02d' $((++n))) pc $addr  $match"
done

